import {Box, Button, ButtonLink, Dialog, DialogFooter, Tag} from '@dagster-io/ui-components';
import {useState} from 'react';

type AssetBackfillTargetPartitions = {
  partitionKeys: string[] | null;
  ranges: {start: string; end: string}[] | null;
};
import {escapePartitionKey} from '../../partitions/SpanRepresentation';
import {TruncatedTextWithFullTextOnHover} from '../../ui/TruncatedTextWithFullTextOnHover';
import {VirtualizedItemListForDialog} from '../../ui/VirtualizedItemListForDialog';
import {numberFormatter} from '../../ui/formatters';

/**
 * Format a range for display (without brackets).
 * Uses proper escaping for partition keys with special characters.
 */
function formatRangeForDisplay(start: string, end: string): string {
  return `${escapePartitionKey(start)}...${escapePartitionKey(end)}`;
}

const COLLATOR = new Intl.Collator(navigator.language, {sensitivity: 'base', numeric: true});

export const TargetPartitionsDisplay = ({
  targetPartitionCount,
  targetPartitions,
}: {
  targetPartitionCount?: number;
  targetPartitions?: Pick<AssetBackfillTargetPartitions, 'partitionKeys' | 'ranges'> | null;
}) => {
  const [isDialogOpen, setIsDialogOpen] = useState(false);

  const {partitionKeys, ranges} = targetPartitions || {};

  if (partitionKeys) {
    if (partitionKeys.length <= 3) {
      return (
        <Box flex={{direction: 'row', gap: 8, wrap: 'wrap'}}>
          {partitionKeys.map((p) => (
            <Tag key={p}>{p}</Tag>
          ))}
        </Box>
      );
    }

    return (
      <>
        <ButtonLink onClick={() => setIsDialogOpen(true)}>
          {numberFormatter.format(partitionKeys.length)} partitions
        </ButtonLink>
        <Dialog
          isOpen={isDialogOpen}
          title={`Partition selection (${partitionKeys.length})`}
          onClose={() => setIsDialogOpen(false)}
        >
          <div style={{height: '340px', overflow: 'hidden'}}>
            <VirtualizedItemListForDialog
              items={[...partitionKeys].sort((a, b) => COLLATOR.compare(a, b))}
              renderItem={(assetKey) => (
                <div key={assetKey}>
                  <TruncatedTextWithFullTextOnHover text={assetKey} />
                </div>
              )}
            />
          </div>
          <DialogFooter topBorder>
            <Button onClick={() => setIsDialogOpen(false)}>Close</Button>
          </DialogFooter>
        </Dialog>
      </>
    );
  }

  if (ranges) {
    if (ranges.length === 1) {
      // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
      const {start, end} = ranges[0]!;
      return <div>{formatRangeForDisplay(start, end)}</div>;
    }

    return (
      <>
        <ButtonLink onClick={() => setIsDialogOpen(true)}>
          {numberFormatter.format(ranges.length)} ranges
        </ButtonLink>
        <Dialog
          isOpen={isDialogOpen}
          title={`Partition selection (${ranges?.length})`}
          onClose={() => setIsDialogOpen(false)}
        >
          <div style={{height: '340px', overflow: 'hidden'}}>
            <VirtualizedItemListForDialog
              items={ranges || []}
              renderItem={({start, end}) => {
                return <div key={`${start}:${end}`}>{formatRangeForDisplay(start, end)}</div>;
              }}
            />
          </div>
          <DialogFooter topBorder>
            <Button onClick={() => setIsDialogOpen(false)}>Close</Button>
          </DialogFooter>
        </Dialog>
      </>
    );
  }

  return (
    <div>
      {targetPartitionCount === 0
        ? '-'
        : targetPartitionCount === 1
          ? '1 partition'
          : `${targetPartitionCount} partitions`}
    </div>
  );
};
